// Faktisk Studio · Kontokart · CSS for nettverkskloden (beskyttet mot faktisk.no-stilene)
var KK_CSS_KLODE = "
.fkn.fkn{all:initial;display:block;box-sizing:border-box;font-family:"Unica77","Helvetica Neue",Helvetica,Arial,sans-serif;font-weight:300;line-height:1.4;color:#212121;text-align:left;-webkit-font-smoothing:antialiased;container-type:inline-size;max-width:var(--lab_page_width,720px);margin:0 auto;padding:.7rem 0}
.fkn.fkn *,.fkn.fkn *::before,.fkn.fkn *::after{box-sizing:border-box;margin:0;padding:0;border:0;background:none;font:inherit;line-height:inherit;color:inherit;letter-spacing:normal;text-transform:none;text-indent:0;text-decoration:none;text-align:inherit;list-style:none;float:none;max-width:none;min-width:0;min-height:0;box-shadow:none;outline:0;quotes:none;vertical-align:baseline}
.fkn.fkn .fkn-box{position:relative;border-radius:16px;overflow:hidden;background:linear-gradient(180deg,#F5F8FF 0%,#EAF0FF 60%,#E3EBFF 100%)}
.fkn.fkn .fkn-map{position:relative;aspect-ratio:2/1}
.fkn.fkn .fkn-map canvas{position:absolute;left:0;top:0;width:100%;height:100%;display:block}
.fkn.fkn .fkn-pill{position:absolute;left:0;top:0;display:inline-flex;align-items:center;gap:.3rem;white-space:nowrap;background:#fff;border:1px solid rgba(0,80,252,.22);border-radius:999px;padding:.16rem .6rem;font-size:clamp(11px,1.85cqw,14px);line-height:1.3;color:#212121;box-shadow:0 2px 8px rgba(0,40,140,.10);transition:opacity .25s;z-index:1}
.fkn.fkn .fkn-pill i{font-style:normal;font-weight:500;font-size:.85em;background:#0050FC;color:#fff;border-radius:999px;min-width:1.35em;height:1.35em;display:inline-flex;align-items:center;justify-content:center;padding:0 .3em}
.fkn.fkn .fkn-pill--no{background:#0050FC;color:#fff;border-color:#0050FC;font-weight:500;font-size:clamp(12px,2.2cqw,16px);padding:.32rem .95rem;box-shadow:0 4px 14px rgba(0,40,140,.22);z-index:3}
.fkn.fkn .fkn-bottom{position:relative;z-index:2;margin-top:clamp(-70px,-9cqw,-34px);padding:clamp(30px,5.5cqw,48px) clamp(14px,3cqw,26px) clamp(12px,2.2cqw,18px);background:linear-gradient(180deg,rgba(234,240,255,0) 0%,rgba(232,239,255,.9) clamp(30px,5.5cqw,48px),#E3EBFF 100%)}
.fkn.fkn .fkn-acc{display:flex;flex-wrap:wrap;gap:6px;justify-content:center}
.fkn.fkn .fkn-chip{cursor:pointer;background:rgba(255,255,255,.85);border:1px solid rgba(0,80,252,.18);border-radius:999px;padding:.26rem .75rem;font-size:clamp(12px,1.95cqw,14px);line-height:1.35;color:#212121;white-space:nowrap;transition:background .15s,border-color .15s,color .15s}
.fkn.fkn .fkn-chip:hover{border-color:rgba(0,80,252,.5)}
.fkn.fkn .fkn-chip.is-on{background:#0050FC;border-color:#0050FC;color:#fff}
.fkn.fkn .fkn-chip--na{color:#7A7A7A;border-style:dashed}
.fkn.fkn .fkn-chip--na.is-on{color:#fff;border-style:solid}
.fkn.fkn .fkn-chip:focus-visible{outline:2px solid #0050FC;outline-offset:2px}
.fkn.fkn .fkn-hint{text-align:center;font-size:clamp(13.5px,2.3cqw,17px);font-weight:500;line-height:1.35;color:#212121;margin:0 auto 12px;max-width:40em;min-height:2.7em;display:flex;align-items:flex-end;justify-content:center}
.fkn.fkn .fkn-hint b{font-weight:500;color:#0050FC;margin-right:.3em}
.fkn.fkn .fkn-legend{display:flex;flex-wrap:wrap;justify-content:center;gap:.2rem 1rem;margin-top:12px;font-size:clamp(10.5px,1.6cqw,12px);color:#5A5A5A;line-height:1.4}
.fkn.fkn .fkn-legend span{display:inline-flex;align-items:center;gap:.3rem}
.fkn.fkn .fkn-dot{width:8px;height:8px;border-radius:50%;background:#0050FC;display:inline-block}
.fkn.fkn .fkn-ring{width:9px;height:9px;border-radius:50%;border:1.2px dashed #0050FC;display:inline-block}
.fkn.fkn .fkn-post{width:10px;height:7px;border-radius:2px;border:1.2px solid #0050FC;background:#fff;display:inline-block}
.fkn.fkn .fkn-source{text-align:center;margin-top:5px;color:#767676;font-size:clamp(10px,1.5cqw,11.5px);line-height:1.45}
.fkn.fkn .fkn-pill--grp{background:#fff;color:#0050FC;border:1.5px solid #0050FC;font-weight:500}
.fkn.fkn .fkn-chip--ex{border-color:#0050FC;border-width:1.5px}
.fkn.fkn .fkn-chip em{font-style:normal;font-size:.8em;margin-left:.35em;color:#0050FC;font-weight:500}
.fkn.fkn .fkn-chip.is-on em{color:#fff}
@media (max-width:480px){.fkn.fkn .fkn-map{aspect-ratio:1.42/1}
.fkn.fkn .fkn-bottom{padding:26px 12px 12px}
.fkn.fkn .fkn-hint{font-size:13.5px;margin-bottom:9px}
.fkn.fkn .fkn-acc{gap:4px}
.fkn.fkn .fkn-chip{font-size:11.5px;padding:.17rem .5rem}
.fkn.fkn .fkn-legend{margin-top:9px}}

.fkn.fkn .fkn-map{aspect-ratio:1.5/1;cursor:grab;touch-action:pan-y;user-select:none;-webkit-user-select:none}
.fkn.fkn .fkn-map.is-drag{cursor:grabbing}
.fkn.fkn .fkn-pill{pointer-events:none;transition:none}
.fkn.fkn .fkn-chip.is-rel{border-color:#0050FC;background:#fff;color:#0050FC}
@media (max-width:480px){.fkn.fkn .fkn-map{aspect-ratio:1.08/1}}
";

