// Faktisk Studio · delt dialog-modul
// window.prompt og window.confirm er blokkert i Electron. Vi bygger
// en custom modal som matcher Faktisk-designet og returnerer Promise.

(function () {
  function ensureContainer() {
    let host = document.getElementById('faktisk-dialog-host');
    if (host) return host;
    host = document.createElement('div');
    host.id = 'faktisk-dialog-host';
    document.body.appendChild(host);
    const style = document.createElement('style');
    style.textContent = `
      #faktisk-dialog-host {
        position: fixed; inset: 0; display: none;
        align-items: center; justify-content: center;
        background: rgba(0,0,0,0.45);
        z-index: 99999;
        font-family: var(--font-regular), "Helvetica Neue", sans-serif;
      }
      #faktisk-dialog-host.open { display: flex; }
      .fd-card {
        background: #fff;
        color: #212121;
        border-radius: 14px;
        padding: 24px 28px;
        width: 420px;
        max-width: calc(100vw - 40px);
        box-shadow: 0 24px 60px rgba(0,0,0,0.4);
        display: flex;
        flex-direction: column;
        gap: 14px;
      }
      .fd-message {
        font-size: 15px;
        line-height: 1.4;
        margin: 0;
        color: #212121;
        font-weight: 500;
      }
      .fd-input {
        background: #f0f0f0;
        border: 0;
        outline: 0;
        border-radius: 7px;
        padding: 10px 12px;
        font-size: 14px;
        font-family: inherit;
        color: #212121;
        font-weight: 500;
      }
      .fd-input:focus { outline: 2px solid #0050FC; }
      .fd-row {
        display: flex;
        gap: 10px;
        justify-content: flex-end;
        margin-top: 4px;
      }
      .fd-btn {
        padding: 10px 20px;
        font-size: 14px;
        font-weight: bold;
        border: 0;
        border-radius: 9px;
        cursor: pointer;
        font-family: inherit;
      }
      .fd-btn-primary { background: #0050FC; color: #fff; }
      .fd-btn-primary:hover { background: #0040D9; }
      .fd-btn-cancel { background: #e0e0e0; color: #212121; }
      .fd-btn-cancel:hover { background: #d0d0d0; }
      .fd-btn-danger { background: #d04040; color: #fff; }
      .fd-btn-danger:hover { background: #e85050; }
      .fd-progress-label {
        font-size: 13px;
        color: #555;
        margin: 0;
      }
      .fd-progress {
        height: 8px;
        background: #e0e0e0;
        border-radius: 4px;
        overflow: hidden;
      }
      .fd-progress__bar {
        height: 100%;
        background: #0050FC;
        transition: width 0.2s;
      }
      .project-card {
        background: #0050FC;
        color: #fff;
        border-radius: 9px;
        padding: 12px 16px;
        cursor: pointer;
        display: flex;
        flex-direction: column;
        gap: 4px;
        position: relative;
        transition: background 0.15s;
      }
      .project-card:hover { background: #0040D9; }
      .project-card__name { font-weight: bold; font-size: 14px; }
      .project-card__meta { font-size: 11px; opacity: 0.85; }
      .project-card__delete {
        position: absolute; top: 6px; right: 8px;
        background: rgba(255,255,255,0.18); color: #fff;
        width: 22px; height: 22px; border-radius: 4px;
        display: none; align-items: center; justify-content: center;
        font-size: 14px; cursor: pointer; border: 0;
      }
      .project-card:hover .project-card__delete { display: flex; }
      .project-card__delete:hover { background: rgba(255,80,80,0.85); }
    `;
    document.head.appendChild(style);
    return host;
  }

  function open(html, onMount) {
    const host = ensureContainer();
    host.innerHTML = `<div class="fd-card">${html}</div>`;
    host.classList.add('open');
    if (onMount) onMount(host);
    return () => { host.classList.remove('open'); host.innerHTML = ''; };
  }

  function prompt(message, defaultValue) {
    return new Promise(resolve => {
      const close = open(`
        <p class="fd-message"></p>
        <input class="fd-input" type="text">
        <div class="fd-row">
          <button class="fd-btn fd-btn-cancel" data-act="cancel">Avbryt</button>
          <button class="fd-btn fd-btn-primary" data-act="ok">OK</button>
        </div>
      `, host => {
        host.querySelector('.fd-message').textContent = message || '';
        const input = host.querySelector('.fd-input');
        input.value = defaultValue || '';
        setTimeout(() => { input.focus(); input.select(); }, 30);
        const cleanup = result => { close(); resolve(result); };
        host.querySelector('[data-act="ok"]').onclick = () => cleanup(input.value);
        host.querySelector('[data-act="cancel"]').onclick = () => cleanup(null);
        input.onkeydown = e => {
          if (e.key === 'Enter') cleanup(input.value);
          if (e.key === 'Escape') cleanup(null);
        };
      });
    });
  }

  function confirm(message, danger) {
    return new Promise(resolve => {
      const okClass = danger ? 'fd-btn-danger' : 'fd-btn-primary';
      const close = open(`
        <p class="fd-message"></p>
        <div class="fd-row">
          <button class="fd-btn fd-btn-cancel" data-act="cancel">Avbryt</button>
          <button class="fd-btn ${okClass}" data-act="ok">${danger ? 'Slett' : 'OK'}</button>
        </div>
      `, host => {
        host.querySelector('.fd-message').textContent = message || '';
        const cleanup = result => { close(); resolve(result); };
        host.querySelector('[data-act="ok"]').onclick = () => cleanup(true);
        host.querySelector('[data-act="cancel"]').onclick = () => cleanup(false);
        document.onkeydown = e => {
          if (e.key === 'Escape') { document.onkeydown = null; cleanup(false); }
        };
      });
    });
  }

  function alert(message) {
    return new Promise(resolve => {
      const close = open(`
        <p class="fd-message"></p>
        <div class="fd-row">
          <button class="fd-btn fd-btn-primary" data-act="ok">OK</button>
        </div>
      `, host => {
        host.querySelector('.fd-message').textContent = message || '';
        const cleanup = () => { close(); resolve(); };
        host.querySelector('[data-act="ok"]').onclick = cleanup;
      });
    });
  }

  window.faktiskDialog = { prompt, confirm, alert };
})();

shared/embed-tokens.js:
// Faktisk embed-tokens — sentral kilde for alle plugins.
//
// Dette er den KANONISKE kopien. Ved bygging av bundle.json kopieres denne
// filen inn i hver plugin/<id>/shared/embed-tokens.js. Alle plugins bruker
// window.FaktiskEmbedBase.* i sin buildEmbedSnippet.
//
// Tokens matcher faktisk.no sin typografi:
// - Unica77 er UI/caption/factbox-fonten
// - #0050FC er Faktisk brand-blå
// - Font-vektene 300/500 er de Labrador-siden faktisk laster
//
// Endringer her får effekt i alle embeds ved neste build+release.
// I fremtidig native-migrering vil Labrador-temaet definere de samme
// --fk-*-variablene på artikkel-nivå, og embeds arver dem gratis.

(function (root) {
  'use strict';

  const TOKENS = {
    // Typografi
    font:         '"Unica77", "Helvetica Neue", Helvetica, Arial, sans-serif',
    fwNormal:     300,   // Unica77 Light
    fwBold:       500,   // Unica77 Medium
    lineHeight:   1.4,

    // Farger
    ink:          '#212121',   // hovedtekst
    inkDim:       '#5A5A5A',   // sekundærtekst
    white:        '#FFFFFF',
    blue:         '#0050FC',   // Faktisk brand-blå
    surface:      '#D9D9D9',   // container-bakgrunn (lys grå)
    surfaceDark:  '#C3C3C3',   // mørkere container (feks bildeanalyse par-container)

    // Geometri
    radiusSm:     '4px',
    radiusMd:     '8px',
    radiusLg:     '16px',

    // Skygger
    shadowSm:     '0 2px 8px rgba(0,0,0,0.10)',
    shadowMd:     '0 4px 16px rgba(0,0,0,0.15)',
    shadowLg:     '0 10px 30px rgba(0,0,0,0.45), 0 2px 6px rgba(0,0,0,0.3)',

    // Spacing (unicorn-scale)
    spaceXs:      '4px',
    spaceSm:      '8px',
    spaceMd:      '16px',
    spaceLg:      '24px',
    spaceXl:      '32px',
  };

  /**
   * Genererer CSS-variabel-blokka som skal ligge på embed-roten.
   * Kall denne først i buildEmbedSnippet slik at plugin-spesifikk CSS
   * kan bruke `var(--fk-blue)`, `var(--fk-font)` osv.
   *
   * @param {string} scope - Klassen som identifiserer denne embed-instansen
   *                        (feks 'ffes-abc123' eller 'banl-xyz789')
   * @returns {string} CSS-tekst
   */
  function getBaseCss(scope) {
    return `
    .${scope} {
      --fk-font: ${TOKENS.font};
      --fk-fw-normal: ${TOKENS.fwNormal};
      --fk-fw-bold: ${TOKENS.fwBold};
      --fk-line-height: ${TOKENS.lineHeight};
      --fk-ink: ${TOKENS.ink};
      --fk-ink-dim: ${TOKENS.inkDim};
      --fk-white: ${TOKENS.white};
      --fk-blue: ${TOKENS.blue};
      --fk-surface: ${TOKENS.surface};
      --fk-surface-dark: ${TOKENS.surfaceDark};
      --fk-radius-sm: ${TOKENS.radiusSm};
      --fk-radius-md: ${TOKENS.radiusMd};
      --fk-radius-lg: ${TOKENS.radiusLg};
      --fk-shadow-sm: ${TOKENS.shadowSm};
      --fk-shadow-md: ${TOKENS.shadowMd};
      --fk-shadow-lg: ${TOKENS.shadowLg};
      --fk-space-xs: ${TOKENS.spaceXs};
      --fk-space-sm: ${TOKENS.spaceSm};
      --fk-space-md: ${TOKENS.spaceMd};
      --fk-space-lg: ${TOKENS.spaceLg};
      --fk-space-xl: ${TOKENS.spaceXl};

      font-family: var(--fk-font);
      font-weight: var(--fk-fw-normal);
      line-height: var(--fk-line-height);
      color: var(--fk-ink);
    }`;
  }


  /**
   * Beskytter en embed mot stilarket på siden den limes inn i (faktisk.no / Labrador).
   * Opt-in: kall på hele CSS-teksten til embedden før den legges i <style>.
   *  - roten (.scope) nullstilles med all:initial og får Faktisk-font/farge/linjehøyde
   *  - alle etterkommere nullstilles (margin, padding, border, font, listetegn …)
   *  - alle regler prefikses med dobbel rotklasse (.scope.scope …) så de veier tyngre enn sidens regler
   *  - font-weight bold/600/700 → 500 og normal/400 → 300 (faktisk.no laster bare Unica77 300 og 500)
   * Sidens regler med !important kan ingen embed overstyre.
   *
   * @param {string} css   - embeddens CSS
   * @param {string} scope - klassen på embeddens rot-element (uten punktum)
   * @returns {string} beskyttet CSS
   */
  function isolate(css, scope) {
    const R = '.' + scope, RR = R + R;
    css = String(css || '')
      .replace(/font-weight:\s*(bold|700|600|bolder)\b/g, 'font-weight: ' + TOKENS.fwBold)
      .replace(/font-weight:\s*(normal|400)\b/g, 'font-weight: ' + TOKENS.fwNormal);
    function fixSel(sel) {
      return sel.split(',').map(s => s.trim()).filter(Boolean).map(s => {
        if (s.startsWith(R) && !/[\w-]/.test(s.charAt(R.length) || ' ')) return RR + s.slice(R.length);
        return RR + ' ' + s;
      }).join(',');
    }
    function walk(src) {
      let out = '', i = 0;
      while (i < src.length) {
        const j = src.indexOf('{', i);
        if (j < 0) { out += src.slice(i); break; }
        const head = src.slice(i, j), hs = head.trim();
        if (hs.charAt(0) === '@') {
          let depth = 1, k = j + 1;
          while (k < src.length && depth) { if (src[k] === '{') depth++; else if (src[k] === '}') depth--; k++; }
          const inner = src.slice(j + 1, k - 1);
          out += head + '{' + (/^@(media|container|supports)/.test(hs) ? walk(inner) : inner) + '}';
          i = k; continue;
        }
        const k = src.indexOf('}', j);
        out += head.slice(0, head.length - head.trimStart().length) + fixSel(hs) + src.slice(j, k + 1);
        i = k + 1;
      }
      return out;
    }
    const reset = `
    ${RR} { all: initial; display: block; box-sizing: border-box; font-family: ${TOKENS.font}; font-weight: ${TOKENS.fwNormal};
      line-height: ${TOKENS.lineHeight}; color: ${TOKENS.ink}; text-align: left; -webkit-font-smoothing: antialiased; }
    ${RR} *, ${RR} *::before, ${RR} *::after { box-sizing: border-box; margin: 0; padding: 0; border: 0; background: none;
      font: inherit; line-height: inherit; color: inherit; letter-spacing: normal; text-transform: none; text-indent: 0;
      text-decoration: none; text-align: inherit; list-style: none; float: none; max-width: none; min-width: 0;
      min-height: 0; box-shadow: none; outline: 0; quotes: none; vertical-align: baseline; }
    ${RR} img, ${RR} svg, ${RR} canvas, ${RR} video { display: block; max-width: none; height: auto; }
`;
    return reset + walk(css);
  }

  root.FaktiskEmbedBase = { TOKENS, getBaseCss, isolate };
})(typeof window !== 'undefined' ? window : globalThis);

shared/fk-import.js:
// Faktisk Studio · felles filimport (CSV, TSV, TXT og Excel .xlsx) — kanonisk kopi i plugins/_shared/.
//
//   FaktiskImport.readFile(file)            → Promise<{ sheets: [{ name, rows: string[][] }] }>
//   FaktiskImport.openDialog({ title, fields, onApply })
//        fields:  [{ key, label, guess: /regex for kolonneoverskrift/, required }]
//        onApply: (objekter[]) — én per datarad, med feltene som nøkler
//
// Ingen eksterne bibliotek: .xlsx pakkes ut med nettleserens DecompressionStream og leses med DOMParser.
// CSV: finner skilletegn selv (semikolon, komma, tabulator), støtter "sitert, tekst", og faller tilbake til
// Windows-1252 når fila ikke er gyldig UTF-8 (vanlig for CSV lagret fra norsk Excel).
(function (root) {
  'use strict';

  // ---------- CSV / TSV ----------
  function decodeText(buf) {
    var u = new Uint8Array(buf), s;
    try { s = new TextDecoder('utf-8', { fatal: true }).decode(u); }
    catch (e) { s = new TextDecoder('windows-1252').decode(u); }
    return s.replace(/^﻿/, '');
  }
  function sniffDelim(text) {
    var line = text.split(/\r?\n/).find(function (l) { return l.trim(); }) || '';
    var best = '\t', n = -1;
    ['\t', ';', ','].forEach(function (d) {
      var c = 0, q = false;
      for (var i = 0; i < line.length; i++) { var ch = line[i]; if (ch === '"') q = !q; else if (!q && ch === d) c++; }
      if (c > n) { n = c; best = d; }
    });
    return best;
  }
  function parseDelimited(text, d) {
    d = d || sniffDelim(text);
    var rows = [], row = [], cell = '', q = false;
    for (var i = 0; i < text.length; i++) {
      var ch = text[i];
      if (q) {
        if (ch === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; }
        else cell += ch;
      } else if (ch === '"' && cell === '') q = true;
      else if (ch === d) { row.push(cell); cell = ''; }
      else if (ch === '\n' || ch === '\r') {
        if (ch === '\r' && text[i + 1] === '\n') i++;
        row.push(cell); rows.push(row); row = []; cell = '';
      } else cell += ch;
    }
    if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
    return clean(rows);
  }
  function clean(rows) {
    rows = rows.map(function (r) { return r.map(function (c) { return String(c == null ? '' : c).trim(); }); })
      .filter(function (r) { return r.some(function (c) { return c !== ''; }); });
    var w = rows.reduce(function (m, r) { return Math.max(m, r.length); }, 0);
    // fjern tomme kolonner helt til høyre
    while (w > 0 && rows.every(function (r) { return !r[w - 1]; })) w--;
    return rows.map(function (r) { var o = r.slice(0, w); while (o.length < w) o.push(''); return o; });
  }

  // ---------- XLSX (zip + XML) ----------
  function unzip(buf) {
    var dv = new DataView(buf), u = new Uint8Array(buf), eocd = -1;
    for (var i = u.length - 22; i >= Math.max(0, u.length - 66000); i--) if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
    if (eocd < 0) throw new Error('Fila ser ikke ut som en gyldig .xlsx (fant ikke zip-katalog).');
    var n = dv.getUint16(eocd + 10, true), off = dv.getUint32(eocd + 16, true), files = {};
    for (var k = 0; k < n; k++) {
      if (dv.getUint32(off, true) !== 0x02014b50) break;
      var method = dv.getUint16(off + 10, true), csize = dv.getUint32(off + 20, true);
      var nlen = dv.getUint16(off + 28, true), xlen = dv.getUint16(off + 30, true), clen = dv.getUint16(off + 32, true);
      var lho = dv.getUint32(off + 42, true), name = new TextDecoder().decode(u.subarray(off + 46, off + 46 + nlen));
      var dstart = lho + 30 + dv.getUint16(lho + 26, true) + dv.getUint16(lho + 28, true);
      files[name] = { method: method, data: u.subarray(dstart, dstart + csize) };
      off += 46 + nlen + xlen + clen;
    }
    return files;
  }
  async function inflate(entry) {
    if (entry.method === 0) return new TextDecoder().decode(entry.data);
    if (entry.method !== 8) throw new Error('Ukjent komprimering i .xlsx (metode ' + entry.method + ').');
    var ds = new Blob([entry.data]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
    return await new Response(ds).text();
  }
  function xml(s) { return new DOMParser().parseFromString(s, 'application/xml'); }
  function kids(el, tag) { return Array.prototype.filter.call(el.childNodes, function (n) { return n.localName === tag; }); }
  function txt(el) { return Array.prototype.map.call(el.getElementsByTagNameNS('*', 't'), function (t) { return t.textContent; }).join(''); }
  function colIdx(ref) { var m = /^([A-Z]+)/.exec(ref || ''), c = 0; if (!m) return -1; for (var i = 0; i < m[1].length; i++) c = c * 26 + (m[1].charCodeAt(i) - 64); return c - 1; }
  function fmtNum(v) { var n = +v; if (!isFinite(n)) return v; return String(Math.round(n * 1e9) / 1e9); }

  async function parseXlsx(buf) {
    var files = unzip(buf), get = async function (p) { return files[p] ? await inflate(files[p]) : null; };
    var shared = [], ss = await get('xl/sharedStrings.xml');
    if (ss) Array.prototype.forEach.call(xml(ss).getElementsByTagNameNS('*', 'si'), function (si) { shared.push(txt(si)); });
    var wb = xml(await get('xl/workbook.xml') || '<workbook/>'), rels = {}, relsX = await get('xl/_rels/workbook.xml.rels');
    if (relsX) Array.prototype.forEach.call(xml(relsX).getElementsByTagNameNS('*', 'Relationship'), function (r) { rels[r.getAttribute('Id')] = r.getAttribute('Target'); });
    var sheets = [];
    var list = Array.prototype.slice.call(wb.getElementsByTagNameNS('*', 'sheet'));
    for (var i = 0; i < list.length; i++) {
      var s = list[i], rid = s.getAttribute('r:id') || s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships', 'id');
      var target = rels[rid] || ('worksheets/sheet' + (i + 1) + '.xml');
      var path = target.replace(/^\//, '').replace(/^xl\//, ''); path = 'xl/' + path;
      var sx = await get(path); if (!sx) continue;
      var rows = [];
      Array.prototype.forEach.call(xml(sx).getElementsByTagNameNS('*', 'row'), function (r) {
        var ri = (+r.getAttribute('r') || rows.length + 1) - 1, out = [];
        kids(r, 'c').forEach(function (c, ci) {
          var t = c.getAttribute('t'), idx = colIdx(c.getAttribute('r')); if (idx < 0) idx = ci;
          var v = kids(c, 'v')[0], val = '';
          if (t === 's') val = shared[+(v && v.textContent)] || '';
          else if (t === 'inlineStr') { var is = kids(c, 'is')[0]; val = is ? txt(is) : ''; }
          else if (t === 'b') val = v && v.textContent === '1' ? 'SANN' : 'USANN';
          else if (t === 'str' || t === 'e') val = v ? v.textContent : '';
          else val = v ? fmtNum(v.textContent) : '';
          out[idx] = val;
        });
        for (var k = 0; k < out.length; k++) if (out[k] == null) out[k] = '';
        rows[ri] = out;
      });
      for (var k2 = 0; k2 < rows.length; k2++) if (!rows[k2]) rows[k2] = [];
      sheets.push({ name: s.getAttribute('name') || ('Ark ' + (i + 1)), rows: clean(rows) });
    }
    if (!sheets.length) throw new Error('Fant ingen ark i .xlsx-fila.');
    return sheets;
  }

  async function readFile(file) {
    var name = (file && file.name || '').toLowerCase(), buf = await file.arrayBuffer();
    if (/\.xlsx$/.test(name)) return { sheets: await parseXlsx(buf) };
    if (/\.(xls|numbers|ods)$/.test(name)) throw new Error('Dette formatet støttes ikke direkte. Lagre som .xlsx eller .csv og prøv igjen.');
    var text = decodeText(buf);
    return { sheets: [{ name: file.name, rows: parseDelimited(text, /\.tsv$/.test(name) ? '\t' : null) }] };
  }

  // ---------- Dialog: velg ark, overskriftsrad og kolonne per felt ----------
  var CSS = '.fki-ov{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:center;justify-content:center;font:13px/1.4 -apple-system,"Helvetica Neue",Arial,sans-serif;color:#fff}'
    + '.fki{background:#3c3c3c;border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,.5);width:min(860px,92vw);max-height:88vh;display:flex;flex-direction:column;padding:18px 20px;gap:12px}'
    + '.fki h3{margin:0;font-size:16px}.fki-row{display:flex;flex-wrap:wrap;gap:10px;align-items:center}'
    + '.fki select,.fki input[type=file]{background:#5a5a5a;color:#fff;border:0;border-radius:6px;padding:5px 8px;font:inherit}'
    + '.fki-map{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:8px}.fki-map label{display:flex;flex-direction:column;gap:3px;font-size:12px;color:#ddd}'
    + '.fki-prev{overflow:auto;border-radius:8px;background:#2c2c2c;max-height:42vh}.fki-prev table{border-collapse:collapse;font-size:12px;min-width:100%}'
    + '.fki-prev th,.fki-prev td{padding:4px 8px;border-bottom:1px solid #444;text-align:left;white-space:nowrap;max-width:260px;overflow:hidden;text-overflow:ellipsis}'
    + '.fki-prev th{background:#4a4a4a;position:sticky;top:0}.fki-prev td.on,.fki-prev th.on{background:rgba(0,80,252,.35)}'
    + '.fki-err{background:#7a2b2b;border-radius:6px;padding:8px 10px}.fki-btns{display:flex;justify-content:flex-end;gap:8px}'
    + '.fki-btn{border:0;border-radius:6px;padding:7px 14px;font:inherit;font-weight:bold;cursor:pointer;background:#6a6a6a;color:#fff}.fki-btn--p{background:#0050FC}.fki-btn:disabled{opacity:.4;cursor:default}'
    + '.fki-drop{border:2px dashed #777;border-radius:10px;padding:22px;text-align:center;color:#ccc}.fki-drop.is-over{border-color:#0050FC;color:#fff}.fki small{color:#bbb}';

  function el(tag, cls, html) { var e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }

  function openDialog(opt) {
    if (!document.getElementById('fki-css')) { var st = el('style'); st.id = 'fki-css'; st.textContent = CSS; document.head.appendChild(st); }
    var fields = opt.fields || [], ov = el('div', 'fki-ov'), box = el('div', 'fki');
    ov.appendChild(box); document.body.appendChild(ov);
    var data = null, sheetIdx = 0, header = true, map = {};
    function close() { ov.remove(); document.removeEventListener('keydown', onKey); }
    function onKey(e) { if (e.key === 'Escape') close(); }
    document.addEventListener('keydown', onKey);
    ov.addEventListener('click', function (e) { if (e.target === ov) close(); });

    function guess(heads) {
      map = {};
      fields.forEach(function (f, fi) {
        var hit = -1;
        if (header && f.guess) heads.forEach(function (h, i) { if (hit < 0 && f.guess.test(h) && Object.keys(map).every(function (k) { return map[k] !== i; })) hit = i; });
        if (hit < 0 && !header) hit = fi < heads.length ? fi : -1;
        map[f.key] = hit;
      });
    }
    function rowsNow() { var r = data.sheets[sheetIdx].rows; return header ? r.slice(1) : r; }
    function headsNow() { var r = data.sheets[sheetIdx].rows, w = r[0] ? r[0].length : 0; return header ? r[0] : Array.from({ length: w }, function (_, i) { return 'Kolonne ' + String.fromCharCode(65 + i); }); }

    function pickView(err) {
      box.innerHTML = '<h3>' + esc(opt.title || 'Importer fil') + '</h3>'
        + (err ? '<div class="fki-err">' + esc(err) + '</div>' : '')
        + '<div class="fki-drop">Slipp en fil her, eller <label style="text-decoration:underline;cursor:pointer">velg fil<input type="file" accept=".xlsx,.csv,.tsv,.txt" hidden></label><br><small>Excel (.xlsx), CSV eller TSV. Fra Google Sheets: Fil → Last ned → .xlsx eller .csv.</small></div>'
        + '<div class="fki-btns"><button class="fki-btn" data-x>Avbryt</button></div>';
      var inp = box.querySelector('input[type=file]'), drop = box.querySelector('.fki-drop');
      inp.addEventListener('change', function () { if (inp.files[0]) load(inp.files[0]); });
      ['dragenter', 'dragover'].forEach(function (t) { drop.addEventListener(t, function (e) { e.preventDefault(); drop.classList.add('is-over'); }); });
      ['dragleave', 'drop'].forEach(function (t) { drop.addEventListener(t, function (e) { e.preventDefault(); drop.classList.remove('is-over'); }); });
      drop.addEventListener('drop', function (e) { var f = e.dataTransfer.files[0]; if (f) load(f); });
      box.querySelector('[data-x]').addEventListener('click', close);
    }
    async function load(file) {
      try { data = await readFile(file); }
      catch (e) { pickView(e.message || String(e)); return; }
      sheetIdx = 0; header = true;
      if (!data.sheets[0].rows.length) { pickView('Fila er tom.'); return; }
      guess(headsNow()); mapView(file.name);
    }
    function mapView(fname) {
      var heads = headsNow(), rows = rowsNow();
      var colOpts = function (sel) { return '<option value="-1">– ikke bruk –</option>' + heads.map(function (h, i) { return '<option value="' + i + '"' + (i === sel ? ' selected' : '') + '>' + esc(h || 'Kolonne ' + String.fromCharCode(65 + i)) + '</option>'; }).join(''); };
      var used = {}; fields.forEach(function (f) { if (map[f.key] >= 0) used[map[f.key]] = 1; });
      box.innerHTML = '<h3>' + esc(opt.title || 'Importer fil') + ' <small>· ' + esc(fname) + '</small></h3>'
        + '<div class="fki-row">'
        + (data.sheets.length > 1 ? '<label>Ark <select data-sheet>' + data.sheets.map(function (s, i) { return '<option value="' + i + '"' + (i === sheetIdx ? ' selected' : '') + '>' + esc(s.name) + '</option>'; }).join('') + '</select></label>' : '')
        + '<label><input type="checkbox" data-head' + (header ? ' checked' : '') + '> Første rad er overskrifter</label>'
        + '<small>' + rows.length + ' rader</small></div>'
        + '<div class="fki-map">' + fields.map(function (f) { return '<label>' + esc(f.label) + (f.required ? ' *' : '') + '<select data-f="' + f.key + '">' + colOpts(map[f.key]) + '</select></label>'; }).join('') + '</div>'
        + '<div class="fki-prev"><table><thead><tr>' + heads.map(function (h, i) { return '<th class="' + (used[i] ? 'on' : '') + '">' + esc(h) + '</th>'; }).join('') + '</tr></thead><tbody>'
        + rows.slice(0, 12).map(function (r) { return '<tr>' + r.map(function (c, i) { return '<td class="' + (used[i] ? 'on' : '') + '">' + esc(c) + '</td>'; }).join('') + '</tr>'; }).join('')
        + '</tbody></table></div>'
        + (rows.length > 12 ? '<small>Viser 12 av ' + rows.length + ' rader.</small>' : '')
        + '<div class="fki-row" style="justify-content:space-between"><label>' + (opt.replaceLabel ? '<input type="checkbox" data-rep checked> ' + esc(opt.replaceLabel) : '') + '</label>'
        + '<div class="fki-btns"><button class="fki-btn" data-back>Annen fil</button><button class="fki-btn" data-x>Avbryt</button><button class="fki-btn fki-btn--p" data-ok>Importer ' + rows.length + ' rader</button></div></div>';
      var ok = box.querySelector('[data-ok]');
      var miss = fields.filter(function (f) { return f.required && !(map[f.key] >= 0); });
      ok.disabled = !!miss.length || !rows.length;
      box.querySelectorAll('select[data-f]').forEach(function (s) { s.addEventListener('change', function () { map[s.dataset.f] = +s.value; mapView(fname); }); });
      var sh = box.querySelector('[data-sheet]'); if (sh) sh.addEventListener('change', function () { sheetIdx = +sh.value; guess(headsNow()); mapView(fname); });
      box.querySelector('[data-head]').addEventListener('change', function (e) { header = e.target.checked; guess(headsNow()); mapView(fname); });
      box.querySelector('[data-back]').addEventListener('click', function () { pickView(); });
      box.querySelector('[data-x]').addEventListener('click', close);
      ok.addEventListener('click', function () {
        var rep = box.querySelector('[data-rep]');
        var objs = rowsNow().map(function (r) { var o = {}; fields.forEach(function (f) { o[f.key] = map[f.key] >= 0 ? (r[map[f.key]] || '') : ''; }); return o; });
        close(); opt.onApply(objs, { replace: rep ? rep.checked : true });
      });
    }
    pickView();
  }

  root.FaktiskImport = { readFile: readFile, openDialog: openDialog, parseDelimited: parseDelimited };
})(typeof window !== 'undefined' ? window : globalThis);

shared/labrador-files.js:
// Faktisk Studio — «Mine filer» + «Last opp fil» fra Labrador (delt fil)
//
// Konfigurasjonsdrevet: monterer et panel per URL-input som finnes på siden,
// med riktig filtype-filter (video/bilde). Injiserer egen CSS — pluginene
// trenger bare <script src="shared/labrador-files.js"> før main.js.
// Hopper over inputs som allerede har fått panel (eller egen implementasjon).
// Kanonisk kilde: plugins/_shared/.
//
// clickLoad: false brukes der flere inputs må fylles før lasting
// (for-og-etter trenger både før- og etter-bilde før «Hent»).

(function () {
  'use strict';
  if (!window.faktisk || !window.faktisk.labradorListFiles) return;

  const MOUNTS = [
    // Video-verktøyene (video-player, looping-video, video-hoydepunkter)
    { url: 'videoUrl',  btn: 'loadVideoBtn', accept: 'video' },
    // Parallax bildecollage + SoMe-bilde (bilde 1)
    { url: 'imgUrl',    btn: 'imgLoadUrl',   accept: 'image' },
    // SoMe-bilde: bilde 2 (delt bilde)
    { url: 'img2Url',   btn: 'img2LoadUrl',  accept: 'image' },
    // Bildemal: bakgrunn + bilde i boks
    { url: 'bgUrl',     btn: 'bgLoadUrl',    accept: 'image' },
    { url: 'shapeUrl',  btn: 'shapeLoadUrl', accept: 'image' },
    // Bilde med markering
    { url: 'urlImage',  btn: 'loadBtn',      accept: 'image' },
    // Før og etter-slider: fyll begge før lasting
    { url: 'urlBefore', btn: 'loadBtn',      accept: 'image', clickLoad: false },
    { url: 'urlAfter',  btn: 'loadBtn',      accept: 'image', clickLoad: false },
  ];

  const EXT = {
    video: /\.(mp4|mov|mpg|mpeg|m4v|webm)(\?|$)/i,
    image: /\.(png|jpe?g|gif|avif|heic|webp)(\?|$)/i,
  };
  const UPLOAD_FILTERS = {
    video: [{ name: 'Video', extensions: ['mp4', 'mov', 'mpg', 'mpeg', 'm4v'] }],
    image: [{ name: 'Bilde', extensions: ['png', 'jpg', 'jpeg', 'gif', 'avif', 'heic', 'webp'] }],
  };
  const TYPE_LABEL = { video: 'VIDEO', image: 'BILDE' };

  let cssInjected = false;
  function injectCss() {
    if (cssInjected) return;
    cssInjected = true;
    const css = document.createElement('style');
    css.textContent = `
      .labf-row { display: flex; gap: 6px; margin-top: 6px; }
      .labf-btn {
        flex: 1; background: rgba(255,255,255,0.14); color: #fff;
        border: 0; border-radius: var(--radius-input, 8px);
        font-family: var(--font-bold, inherit); font-weight: bold;
        font-size: 12px; height: 28px; padding: 0 10px; cursor: pointer;
        white-space: nowrap;
      }
      .labf-btn:hover { background: rgba(255,255,255,0.28); }
      .labf-btn:disabled { opacity: 0.4; cursor: not-allowed; }
      .labf-panel {
        background: var(--bg-input, #fff); border-radius: var(--radius-input, 8px);
        padding: 8px; max-height: 200px; overflow-y: auto;
        display: flex; flex-direction: column; gap: 4px; margin-top: 6px;
      }
      .labf-panel__status { font-size: 12px; color: #666; padding: 2px 4px; }
      .labf-panel__status button {
        background: transparent; border: 0; color: #0050FC;
        font-weight: bold; cursor: pointer; text-decoration: underline;
        font-size: 12px; padding: 0;
      }
      .labf-file {
        display: flex; align-items: center; gap: 8px;
        padding: 5px 6px; border-radius: 6px; cursor: pointer;
        font-size: 12.5px; color: var(--text-input, #222);
      }
      .labf-file:hover { background: rgba(0,0,0,0.08); }
      .labf-file__type {
        font-size: 10px; font-weight: bold; background: #0050FC; color: #fff;
        border-radius: 4px; padding: 1px 5px; flex-shrink: 0;
      }
      .labf-file__name {
        flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
        font-family: var(--font-bold, inherit); font-weight: bold;
      }
      .labf-progress {
        height: 6px; background: rgba(0,0,0,0.15); border-radius: 3px;
        overflow: hidden; margin-top: 4px; display: none;
      }
      .labf-progress__bar {
        height: 100%; width: 0; background: #0050FC; transition: width 0.3s;
      }
    `;
    document.head.appendChild(css);
  }

  const statusEl = document.getElementById('status');
  const setStatus = (msg, isError) => {
    if (!statusEl) return;
    statusEl.textContent = msg || '';
    statusEl.style.color = isError ? '#FFB4B4' : '#fff';
  };

  function mount(cfg) {
    const urlInput = document.getElementById(cfg.url);
    const loadBtn = document.getElementById(cfg.btn);
    if (!urlInput || !loadBtn) return;
    if (urlInput.dataset.labfMounted) return;
    if (cfg.url === 'videoUrl' && document.getElementById('labFilesBtn')) return; // video-sensur har egen
    urlInput.dataset.labfMounted = '1';
    injectCss();

    const anchor = urlInput.closest('.url-row') || urlInput.parentElement;
    if (!anchor || !anchor.parentElement) return;

    const row = document.createElement('div');
    row.className = 'labf-row';
    row.innerHTML =
      '<button class="labf-btn" type="button">Mine filer ▾</button>' +
      '<button class="labf-btn" type="button">Last opp fil…</button>';
    const panel = document.createElement('div');
    panel.className = 'labf-panel';
    panel.style.display = 'none';
    panel.innerHTML = '<div class="labf-panel__status"></div><div class="labf-panel__list"></div>';
    const progress = document.createElement('div');
    progress.className = 'labf-progress';
    progress.innerHTML = '<div class="labf-progress__bar"></div>';

    anchor.insertAdjacentElement('afterend', progress);
    anchor.insertAdjacentElement('afterend', panel);
    anchor.insertAdjacentElement('afterend', row);

    const [filesBtn, uploadBtn] = row.querySelectorAll('button');
    const panelStatus = panel.querySelector('.labf-panel__status');
    const panelList = panel.querySelector('.labf-panel__list');
    const progressBar = progress.querySelector('.labf-progress__bar');
    const extRe = EXT[cfg.accept] || EXT.image;

    function pick(url) {
      urlInput.value = url;
      // Noen plugins lagrer state på input-event — utløs det
      urlInput.dispatchEvent(new Event('input', { bubbles: true }));
      panel.style.display = 'none';
      if (cfg.clickLoad !== false) loadBtn.click();
      else urlInput.focus();
    }

    async function refresh() {
      panelStatus.textContent = 'Henter filer…';
      panelList.innerHTML = '';
      let res;
      try { res = await window.faktisk.labradorListFiles(); }
      catch (err) { panelStatus.textContent = 'Feil: ' + err.message; return; }

      if (!res.loggedIn) {
        panelStatus.innerHTML = 'Ikke innlogget. <button type="button">Koble til Labrador…</button>';
        panelStatus.querySelector('button').addEventListener('click', async () => {
          panelStatus.textContent = 'Logg inn i vinduet som åpnes…';
          const st = await window.faktisk.labradorConnect();
          if (st.loggedIn) refresh();
          else panelStatus.textContent = 'Fikk ikke gyldig innlogging. Prøv igjen.';
        });
        return;
      }

      const matching = res.files.filter(f => extRe.test(f.url));
      panelStatus.textContent = matching.length
        ? matching.length + ' ' + (cfg.accept === 'video' ? 'videoer' : 'bilder') + ' (nyeste først)'
        : 'Ingen ' + (cfg.accept === 'video' ? 'videoer' : 'bilder') + ' lastet opp ennå.';
      matching.slice(0, 60).forEach(f => {
        const item = document.createElement('div');
        item.className = 'labf-file';
        item.innerHTML = '<span class="labf-file__type">' + TYPE_LABEL[cfg.accept] + '</span>'
          + '<span class="labf-file__name"></span>';
        item.querySelector('.labf-file__name').textContent = f.name;
        item.title = f.url;
        item.addEventListener('click', () => pick(f.url));
        panelList.appendChild(item);
      });
    }

    filesBtn.addEventListener('click', () => {
      const open = panel.style.display !== 'none';
      panel.style.display = open ? 'none' : 'flex';
      if (!open) refresh();
    });

    if (cfg.accept === 'image') uploadBtn.title = 'Bilder komprimeres (AVIF + JPG i 1200/2400 px). Alt-klikk for å laste opp originalen.';
    uploadBtn.addEventListener('click', async (ev) => {
      uploadBtn.disabled = true;
      // Alt-klikk: last opp originalen uten komprimering (Studio 0.7.9+)
      const optimize = !(ev && ev.altKey);
      setStatus(optimize ? 'Velg fil — lastes opp til Labrador…' : 'Velg fil — originalen lastes opp uten komprimering…');
      const unsub = window.faktisk.onLabradorUploadProgress
        ? window.faktisk.onLabradorUploadProgress(msg => {
            progress.style.display = 'block';
            progressBar.style.width = msg.percent + '%';
            setStatus(msg.label || ('Laster opp… ' + msg.percent + '% (' + msg.sentMB + ' av ' + msg.totalMB + ' MB)'));
          })
        : () => {};
      try {
        const res = await window.faktisk.labradorUpload({
          filters: UPLOAD_FILTERS[cfg.accept] || UPLOAD_FILTERS.image,
          optimize,
        });
        if (res.canceled) { setStatus(''); return; }
        if (!res.ok) { setStatus(res.error, true); return; }
        if (res.url && res.optimized && res.stats) {
          const kb = n => n >= 1048576 ? (n / 1048576).toFixed(1).replace('.', ',') + ' MB' : Math.round(n / 1024) + ' KB';
          const st = res.stats;
          setStatus('Komprimert ✓ ' + kb(st.origBytes) + ' → ' + kb(st.fallbackBytes)
            + (st.avifBytes ? ' (AVIF ' + kb(st.avifBytes) + ')' : '') + ' · ' + res.variants.width + ' px'
            + (st.reused ? ' · fantes allerede i Labrador' : ''));
          pick(res.url);
        } else if (res.url) {
          setStatus('Lastet opp «' + res.name + '» ✓');
          pick(res.url);
        } else {
          setStatus(res.note || 'Lastet opp, men fant ikke URL — sjekk «Mine filer».', true);
        }
      } catch (err) {
        setStatus('Opplasting feilet: ' + err.message, true);
      } finally {
        unsub();
        uploadBtn.disabled = false;
        setTimeout(() => { progress.style.display = 'none'; progressBar.style.width = '0%'; }, 2000);
      }
    });
  }

  MOUNTS.forEach(mount);
})();

shared/labrador-status.js:
// Faktisk Studio — Labrador-tilkoblingsstatus i toppbaren (delt fil)
//
// Selvforsynt: injiserer egen CSS og en statusbrikke i .topbar__actions.
// Viser tydelig om Studio er koblet til Labrador (grønn prikk) eller ikke
// (grå prikk + «Koble til»). Klikk kobler til / sjekker på nytt.
// Inkluderes med <script src="shared/labrador-status.js"> etter topbaren
// (i src/ på malsiden). Kanonisk kilde: plugins/_shared/.

(function () {
  'use strict';
  if (!window.faktisk || !window.faktisk.labradorStatus) return;
  const bar = document.querySelector('.topbar__actions');
  if (!bar || document.getElementById('labStatusChip')) return;

  const css = document.createElement('style');
  css.textContent = `
    .lab-chip {
      display: flex; align-items: center; gap: 7px;
      background: rgba(255,255,255,0.12);
      border: 0; border-radius: 18px;
      padding: 6px 14px; margin-right: 6px;
      font-family: var(--font-bold, inherit); font-weight: bold;
      font-size: 12px; color: #fff; cursor: pointer;
      white-space: nowrap;
    }
    .lab-chip:hover { background: rgba(255,255,255,0.24); }
    .lab-chip__dot {
      width: 9px; height: 9px; border-radius: 50%;
      background: #999; flex-shrink: 0;
      transition: background 0.2s;
    }
    .lab-chip.on .lab-chip__dot { background: #2ecc5e; box-shadow: 0 0 6px rgba(46,204,94,0.7); }
    .lab-chip.checking .lab-chip__dot { background: #f5c542; }
  `;
  document.head.appendChild(css);

  const chip = document.createElement('button');
  chip.id = 'labStatusChip';
  chip.className = 'lab-chip checking';
  chip.type = 'button';
  chip.innerHTML = '<span class="lab-chip__dot"></span><span class="lab-chip__label">Labrador…</span>';
  bar.insertBefore(chip, bar.firstChild);
  const label = chip.querySelector('.lab-chip__label');

  let connected = false;
  let busy = false;

  function render(state) {
    chip.classList.remove('on', 'checking');
    if (state === 'on') {
      chip.classList.add('on');
      label.textContent = 'Labrador tilkoblet';
      chip.title = 'Koblet til Labrador — «Mine filer» og opplasting virker i alle verktøy. Klikk for å sjekke på nytt.';
    } else if (state === 'checking') {
      chip.classList.add('checking');
      label.textContent = 'Labrador…';
      chip.title = 'Sjekker Labrador-tilkobling…';
    } else {
      label.textContent = 'Koble til Labrador';
      chip.title = 'Ikke innlogget — klikk for å logge inn. Gjelder alle verktøyene.';
    }
  }

  async function check() {
    if (busy) return;
    render('checking');
    try {
      const st = await window.faktisk.labradorStatus();
      connected = !!st.loggedIn;
    } catch (e) {
      connected = false;
    }
    render(connected ? 'on' : 'off');
  }

  chip.addEventListener('click', async () => {
    if (busy) return;
    busy = true;
    try {
      if (connected) {
        busy = false;
        await check();
        return;
      }
      render('checking');
      label.textContent = 'Logg inn i vinduet…';
      const st = await window.faktisk.labradorConnect();
      connected = !!st.loggedIn;
      render(connected ? 'on' : 'off');
    } catch (e) {
      render('off');
    } finally {
      busy = false;
    }
  });

  window.addEventListener('focus', check);
  check();
})();

shared/new-project.js:
// Delt hjelper: kobler #newProjectBtn til stateClear + reload.
// Plugin må ha en knapp med id="newProjectBtn" i topbaren OG sette
// window.PLUGIN_ID til pluginens id (samme som mappe-navnet i plugins/).
(function () {
  document.addEventListener('DOMContentLoaded', function () {
    var btn = document.getElementById('newProjectBtn');
    if (!btn) return;
    btn.addEventListener('click', async function () {
      try {
        var ok = await window.faktiskDialog.confirm(
          'Slett gjeldende arbeid og start på nytt?\n\nLagrede prosjekter beholdes.',
          true
        );
        if (!ok) return;
        var id = window.PLUGIN_ID || (document.querySelector('meta[name="plugin-id"]') || {}).content;
        if (id && window.faktisk && window.faktisk.stateClear) {
          await window.faktisk.stateClear(id);
        }
        location.reload();
      } catch (e) {
        console.error(e);
      }
    });
  });
})();

