/* Diskret versjonsindikator ved siden av logo */
.topbar__version {
  font-family: var(--font-bold);
  font-size: 11px;
  font-weight: bold;
  color: #fff;
  opacity: 0.5;
  letter-spacing: 0.04em;
  white-space: nowrap;
