/* Før og etter slider — plugin-spesifikk styling */

.plugin-page {
  flex: 1;
  display: grid;
  grid-template-columns: 313px 1fr;
  gap: 22px;
  overflow: hidden;
  padding: 4px;
}

.plugin-sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 0 4px 4px;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.3) transparent;
}
.plugin-sidebar::-webkit-scrollbar { width: 8px; }
.plugin-sidebar::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.3);
  border-radius: 4px;
}
/* Kopier embed-knappen pinnes nede så den alltid er synlig */
#copyEmbedBtn {
  position: sticky;
  bottom: 0;
  z-index: 10;
  box-shadow: 0 -10px 14px -4px rgba(157,157,157,0.7);
}

.plugin-sidebar__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.plugin-sidebar__title {
  font-family: var(--font-bold);
  font-size: 22px;
  font-weight: bold;
  color: #212121;
  margin: 0;
  line-height: 1.05;
}

.plugin-sidebar__desc { display: none; }

.plugin-sidebar__spacer { /* deaktivert — tb-section tar all ledig plass */ }

.caption-section { display: flex; flex-direction: column; gap: 3px; }
.caption-input {
  background: var(--bg-input);
  border: 0;
  outline: 0;
  border-radius: 6px;
  padding: 6px 11px;
  font-weight: bold;
  font-size: 12px;
  color: var(--text-input);
  resize: vertical;
  line-height: 1.3;
  font-family: inherit;
}
.caption-input--single { height: 32px; padding: 0 11px; }
.caption-input::placeholder { color: #888; font-weight: normal; }

.plugin-sidebar__status {
  font-size: 13px;
  color: #fff;
  min-height: 18px;
  opacity: 0.85;
}

.url-section { display: flex; flex-direction: column; gap: 6px; }
.url-section--compact { gap: 6px; }
.url-section__label {
  font-family: var(--font-bold);
  font-size: 12px;
  font-weight: bold;
  color: #fff;
}
.url-section__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.link-btn {
  background: transparent;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: rgba(255,255,255,0.5);
  text-underline-offset: 3px;
}
.link-btn:hover { text-decoration-color: #fff; }

.url-row {
  background: var(--bg-input);
  border-radius: 6px;
  padding: 11px 14px;
  display: flex;
  align-items: center;
}
.url-row__input {
  display: block;
  flex: 1;
  background: var(--bg-input);
  border: 0;
  outline: 0;
  padding: 11px 14px;
  border-radius: 6px;
  font-family: var(--font-bold);
  font-size: 12px;
  line-height: 1.3;
  color: var(--text-input);
  font-weight: bold;
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
  appearance: none;
  -webkit-appearance: none;
}
.url-row__input::placeholder { color: #888; font-weight: normal; }

/* Legacy klasse — peker nå til samme stil som btn-mini */
.btn-tiny {
  background: var(--faktisk-blue);
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  padding: 5px 9px;
  border-radius: 6px;
  white-space: nowrap;
  border: 0;
  cursor: pointer;
}
.btn-tiny:hover { background: var(--faktisk-blue-hover); }

.project-row { display: flex; gap: 4px; }
.project-row .project-select { flex: 1; }
.project-select {
  width: 100%;
  height: 32px;
  background: var(--bg-input);
  border: 0;
  border-radius: 6px;
  padding: 0 28px 0 11px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  color: var(--text-input);
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' stroke='%23313131' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/></svg>");
  background-repeat: no-repeat;
  background-position: right 10px center;
}

.btn-primary:disabled { opacity: 0.4; cursor: not-allowed; }

/* Canvas — slider preview */
.plugin-canvas {
  display: flex;
  flex-direction: column;
  /* IKKE overflow:hidden — tekstbokser skal kunne stikke ut av kart-området */
  overflow: visible;
  min-width: 0;
  gap: 20px;
  padding: 8px 0;
}

/* «Før» / «Etter»-bokser over bildet */
.slider-labels {
  display: flex;
  justify-content: space-between;
  align-items: center;
  pointer-events: none;
  flex: 0 0 auto;
}
.slider-label {
  background: #0050FC;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: clamp(14px, 1.8cqw, 22px);
  padding: 0.3em 0.65em;
  border-radius: 5px;
  line-height: 1.25;
}

/* Sidebar: toggle + felt for Før/Etter-tekster */
.labels-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.check-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  cursor: pointer;
  user-select: none;
}
.check-row input[type="checkbox"] {
  accent-color: var(--faktisk-blue);
  margin: 0;
  cursor: pointer;
}
.labels-inputs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
}
.labels-section.is-off .labels-inputs { display: none; }

/* Liten kompakt input — brukt på Før/Etter-tekst-felter (mindre enn URL-felt) */
.input-mini {
  background: var(--bg-input);
  border: 0;
  outline: 0;
  height: 32px;
  padding: 0 11px;
  border-radius: 6px;
  font-family: var(--font-bold);
  font-size: 12px;
  color: var(--text-input);
  font-weight: bold;
  width: 100%;
  box-sizing: border-box;
}
.input-mini::placeholder { color: #888; font-weight: normal; }

.slider-stage {
  position: relative;
  flex: 1;
  background: transparent;
  /* INGEN overflow:hidden her — slipper tekstbokser stikker ut.
     Klippingen skjer på .slider-clipper innenfor. */
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 0;
}

.slider-empty {
  padding: 40px;
  text-align: center;
}
.slider-empty p {
  max-width: 420px;
  font-size: 16px;
  color: #fff;
  margin: 0;
  line-height: 1.4;
}

.slider-preview {
  position: relative;
  width: 100%;
  height: 100%;
  user-select: none;
  container-type: inline-size;
}
/* Klipper for bildene + slider-handle + arrows/dots — tekstbokser ligger UTENFOR */
.slider-clipper {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: 10px;
  background: var(--bg-letterbox);
}

.slider-img {
  position: absolute;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  pointer-events: none;
}

.slider-clip {
  position: absolute;
  width: 100%;
  height: 100%;
  clip-path: inset(0 50% 0 0);
  transition: clip-path 0.05s linear;
  pointer-events: none;
}

.slider-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: clamp(5px, 0.9cqw, 9px);
  background: #fff;
  transform: translateX(-50%);
  cursor: ew-resize;
  z-index: 3;
}

.slider-handle__line {
  position: absolute;
  inset: 0;
  background: #fff;
}

.slider-handle__knob {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: clamp(28px, 4.2cqw, 38px);
  height: clamp(20px, 3cqw, 28px);
  background: #fff;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 6px rgba(0,0,0,0.3);
}
.slider-handle__knob svg {
  width: 78%;
  height: 78%;
}

/* Tekstboks-seksjon i sidebar — Figma-stil med scroll-container */
.tb-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 0 0 auto;
}
.tb-section__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
/* Grå scroll-container som inneholder tekstboks-radene */
.tb-list {
  background: #929292;
  border-radius: 6px;
  padding: 10px 8px;
  max-height: 180px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  scrollbar-width: thin;
  scrollbar-color: #6e6e6e #888;
}
.tb-list::-webkit-scrollbar { width: 8px; }
.tb-list::-webkit-scrollbar-track { background: #888; border-radius: 4px; }
.tb-list::-webkit-scrollbar-thumb { background: #6e6e6e; border-radius: 4px; }
.tb-list:empty::before {
  content: "Ingen tekstbokser ennå. Trykk «+ Legg til»";
  color: rgba(255,255,255,0.85);
  font-size: 12px;
  font-style: italic;
  padding: 4px 2px;
}

.tb-row {
  display: grid;
  grid-template-columns: 24px 1fr 24px 24px;
  gap: 4px;
  align-items: flex-start;
}
.tb-row__chip {
  height: 24px;
  border-radius: 6px;
  cursor: pointer;
  border: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: bold;
  font-family: var(--font-bold);
  color: #fff;
}
.tb-row__chip--light { background: #a2a2a2; }
.tb-row__chip--dark { background: var(--faktisk-blue); }

.tb-row__input {
  background: #D4D4D4;
  border: 0;
  outline: 0;
  border-radius: 6px;
  padding: 4px 9px;
  min-height: 24px;
  font-family: var(--font-bold);
  font-size: 12px;
  color: #212121;
  font-weight: bold;
  resize: vertical;
  line-height: 1.3;
  font-family: inherit;
}
.tb-row__input::placeholder { color: #666; font-weight: normal; }
input.tb-row__input { height: 24px; padding: 0 9px; }
textarea.tb-row__input { min-height: 36px; }

/* Peker-toggle (↗) og slett (×) — like små grå knapper */
.tb-row__btn {
  background: #a2a2a2;
  color: #fff;
  border: 0;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
  font-weight: bold;
  font-family: var(--font-bold);
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tb-row__btn:hover { background: #888; }
.tb-row__btn--active { background: #f18181; }   /* peker aktiv */
.tb-row__btn--del:hover { background: #c95c5c; }

/* Kompakt Figma-knapp — brukes overalt i sidebar */
.btn-mini {
  background: var(--faktisk-blue);
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  padding: 5px 9px;
  border-radius: 6px;
  border: 0;
  cursor: pointer;
  white-space: nowrap;
  line-height: 1.3;
}
.btn-mini:hover:not(:disabled) { background: var(--faktisk-blue-hover); }
.btn-mini:disabled { opacity: 0.4; cursor: not-allowed; }
.btn-mini--block { width: 100%; text-align: center; }
.btn-mini--light { background: #a2a2a2; }
.btn-mini--light:hover:not(:disabled) { background: #888; }

.tb-add-buttons {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

/* Tekstbokser PÅ preview (drag-bare) — matcher embed-størrelser */
.tb-overlay {
  position: absolute;
  padding: 0.45em 0.95em;
  border-radius: 5px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: clamp(14px, 1.8cqw, 26px);
  line-height: 1.25;
  cursor: move;
  user-select: none;
  pointer-events: auto;
  white-space: nowrap;
  transform: translate(-50%, -50%);
  z-index: 4;
  box-shadow: 0 2px 6px rgba(0,0,0,0.3);
}
.tb-overlay--light {
  background: #D9D9D9;
  color: #212121;
  font-weight: normal;
  font-size: clamp(14px, 1.6cqw, 22px);
  white-space: normal;
  word-break: break-word;
  /* Bredden hentes fra --tb-w (settes inline per boks).
     Preview-vinduet er typisk bredt, så ingen mobile-overstyring er nødvendig her. */
  width: var(--tb-w, 28%);
}
.tb-overlay--dark { background: #0050fc; color: #fff; }
/* Resize-håndtak (lite blått punkt nedre-høyre) for light-bokser */
.tb-overlay__resize {
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 12px;
  height: 12px;
  background: #fff;
  border: 2px solid #0050fc;
  border-radius: 50%;
  cursor: ew-resize;
  z-index: 5;
}
.tb-overlay.is-selected { outline: 2px dashed #fff; outline-offset: 2px; }

/* Markeringer (frittstående sirkler) i preview */
.bm-marker {
  position: absolute;
  transform: translate(-50%, -50%);
  aspect-ratio: 1;
  cursor: move;
  z-index: 4;
  box-shadow: 0 2px 6px rgba(0,0,0,0.4);
}
.bm-marker--filled {
  background: var(--mark-color, #0050fc);
  border-radius: 50%;
}
.bm-marker--open {
  border: 4px solid var(--mark-color, #0050fc);
  border-radius: 50%;
  background: transparent;
}
.bm-marker__scale {
  position: absolute;
  right: -8px;
  bottom: -8px;
  width: 16px;
  height: 16px;
  background: #fff;
  border: 2px solid #0050fc;
  border-radius: 50%;
  cursor: nwse-resize;
  z-index: 5;
}

/* Marker-seksjon i sidebar — samme stil som tb-section */
.marker-section { display: flex; flex-direction: column; gap: 8px; flex: 0 0 auto; }

/* Peker-sirkel — bevarer proporsjon (HTML-div, ikke SVG) + puls-ring.
   Farge styres via variant-modifier (--dot-color custom prop). */
.tb-pointer-circle {
  position: absolute;
  width: 28px;
  height: 28px;
  transform: translate(-50%, -50%);
  cursor: move;
  z-index: 5;
  pointer-events: auto;
  --dot-color: #fff;
}
.tb-pointer-circle--dark { --dot-color: #0050fc; }
.tb-pointer-circle--light { --dot-color: #fff; }
/* Åpen ring: erstatt fyll med border + transparent inside */
.tb-pointer-circle--open .tb-pointer-dot-inner {
  background: transparent;
  border: 4px solid var(--dot-color);
  box-sizing: border-box;
}
.tb-pointer-circle--open .tb-pointer-pulse {
  background: transparent;
  border: 3px solid var(--dot-color);
  box-sizing: border-box;
}
/* Skalerings-håndtak på peker-sirkel (lite hvitt punkt nedre-høyre) */
.tb-pointer-scale {
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 12px;
  height: 12px;
  background: #fff;
  border: 2px solid #0050fc;
  border-radius: 50%;
  cursor: nwse-resize;
  z-index: 6;
}
.tb-pointer-dot-inner {
  position: absolute;
  inset: 0;
  background: var(--dot-color);
  border-radius: 50%;
  box-shadow: 0 1px 4px rgba(0,0,0,0.5);
  z-index: 2;
}
.tb-pointer-pulse {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--dot-color);
  opacity: 0.55;
  animation: tb-pulse 1.8s ease-out infinite;
  pointer-events: none;
  z-index: 1;
}
@keyframes tb-pulse {
  0%   { transform: scale(1);   opacity: 0.55; }
  80%  { transform: scale(2.6); opacity: 0;    }
  100% { transform: scale(2.6); opacity: 0;    }
}

/* ============================================================
   Tabell-spesifikt (radkort i sidepanelet + forhåndsvisning)
   ============================================================ */

.ftb-fields {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 10px;
}

/* Radkort — samme mønster som hendelseskart/klippsamler */
.hk-hint {
  font-size: 11px;
  color: rgba(255,255,255,0.65);
  margin: 6px 0 0;
  line-height: 1.4;
}
.hk-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  border-radius: 8px;
  background: rgba(255,255,255,0.07);
  margin-bottom: 6px;
}
.hk-row__top {
  display: flex;
  align-items: center;
  gap: 6px;
}
.hk-row__num {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #0050FC;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.hk-row__title,
.hk-row__img,
.ftb-value {
  box-sizing: border-box;
  background: var(--bg-input, #fff);
  color: #212121;
  border: 0;
  border-radius: 6px;
  font-family: inherit;
  font-size: 12px;
  padding: 5px 8px;
}
.hk-row__title { flex: 1; min-width: 0; font-weight: bold; }
.hk-row__img { width: 100%; font-size: 11px; color: #555; }
.ftb-value {
  width: 54px;
  flex-shrink: 0;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.ks-clip__btns {
  flex-shrink: 0;
  display: inline-flex;
  gap: 2px;
}

.ftb-opts {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ks-check {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  color: #fff;
  cursor: pointer;
  user-select: none;
}
.ks-check input { accent-color: #0050FC; }

/* Forhåndsvisning: rullbar kolonne med embedden i naturlig bredde */
.ftb-stage {
  display: block !important;
  overflow-y: auto;
  padding: 28px 24px;
}
.ftb-previewhost {
  max-width: 720px;
  margin: 0 auto;
}
.ftb-empty {
  color: rgba(255,255,255,0.6);
  text-align: center;
  font-size: 14px;
  margin-top: 15vh;
}

/* Labrador-knapper og filpanel per rad */
.ftb-labrow {
  display: flex;
  gap: 5px;
}
.ftb-labbtn {
  flex: 1;
  background: rgba(255,255,255,0.14);
  color: #fff;
  border: 0;
  border-radius: 6px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 11px;
  height: 24px;
  padding: 0 8px;
  cursor: pointer;
  white-space: nowrap;
}
.ftb-labbtn:hover { background: rgba(255,255,255,0.28); }
.ftb-labbtn:disabled { opacity: 0.5; cursor: default; }
.ftb-labpanel {
  background: var(--bg-input, #fff);
  border-radius: 6px;
  overflow: hidden;
}
.ftb-labpanel__status {
  font-size: 11px;
  color: #555;
  padding: 6px 8px;
}
.ftb-labpanel__status .ftb-labbtn {
  background: #0050FC;
  margin-top: 4px;
}
.ftb-labpanel__list {
  max-height: 150px;
  overflow-y: auto;
  border-top: 1px solid #E5E5E5;
}
.ftb-labfile {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: #212121;
  font-family: inherit;
  font-size: 11px;
  padding: 5px 8px;
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ftb-labfile:hover { background: rgba(0,80,252,0.12); }

/* Ramme-valg: tykkelse + fargevelger side om side */
.ftb-framerow {
  display: flex;
  gap: 6px;
  align-items: center;
}
.ftb-framerow .project-select { flex: 1; }
.ftb-framerow input[type="color"] {
  width: 34px;
  height: 26px;
  border: 0;
  border-radius: 6px;
  padding: 0;
  background: transparent;
  cursor: pointer;
}

/* ============================================================
   Kontokart
   ============================================================ */
.kk-tabs { display: flex; gap: 4px; background: #5a5a5a; padding: 3px; border-radius: 8px; }
.kk-tab { flex: 1; border: 0; border-radius: 6px; padding: 6px 8px; font: inherit; font-size: 12px; font-weight: bold; color: #ddd; background: transparent; cursor: pointer; }
.kk-tab.is-on { background: var(--faktisk-blue); color: #fff; }
.kk-sec { flex: 0 0 auto; }
.kk-sec--small .tb-section__header { margin-bottom: 4px; }
.kk-count { color: #bbb; font-weight: normal; }
.kk-list { max-height: 46vh; display: flex; flex-direction: column; gap: 6px; }
.kk-acc { background: #6a6a6a; border-radius: 8px; padding: 7px; display: flex; flex-direction: column; gap: 5px; border: 1.5px solid transparent; }
.kk-acc.is-ex { border-color: var(--faktisk-blue); }
.kk-acc__top { display: flex; align-items: center; gap: 6px; }
.kk-acc__top .kk-navn { flex: 1; font-weight: bold; }
.kk-two { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.kk-excheck { font-size: 12px; }
.kk-ex { display: flex; flex-direction: column; gap: 5px; }
.kk-ex[hidden] { display: none; }
.kk-gs { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; font-size: 11px; color: #ddd; }
.kk-gs__lab { margin-right: 2px; }
.kk-g { display: inline-flex; align-items: center; gap: 3px; background: #555; border-radius: 999px; padding: 2px 8px 2px 4px; cursor: pointer; }
.kk-g input { margin: 0; }
.kk-paste { display: flex; flex-direction: column; gap: 5px; margin-bottom: 6px; }
.kk-paste[hidden] { display: none; }
.kk-paste textarea { font-family: ui-monospace, Menlo, monospace; font-size: 11px; }
.kk-paste__row { display: flex; justify-content: space-between; align-items: center; gap: 6px; }
.kk-warn { background: #7a4b12; color: #fff; border-radius: 6px; padding: 6px 8px; font-size: 12px; margin-bottom: 6px; }
.kk-warn[hidden] { display: none; }
.kk-demo { align-self: flex-start; font-size: 12px; margin-top: 2px; }
.kk-targets { display: flex; flex-direction: column; gap: 4px; }
.kk-target { display: flex; align-items: center; gap: 4px; }
.kk-target .tb-row__input { flex: 1; min-width: 0; }
.kk-target .kk-short { flex: 0 0 74px; }
.kk-main { display: inline-flex; align-items: center; cursor: pointer; color: #bbb; font-size: 14px; }
.kk-main input { position: absolute; opacity: 0; pointer-events: none; }
.kk-main input:checked + span { color: #E5262A; }
.kk-view[hidden] { display: none; }
.kk-previewhost { max-width: 760px; }
.kk-two > *, .kk-target .tb-row__input, .kk-acc .tb-row__input { min-width: 0; width: 100%; box-sizing: border-box; }
.kk-target .kk-short { width: 74px; }

/* Rulling (05.11.2026): rammen får fast høyde, så sidepanel og forhåndsvisning ruller hver for seg
   i stedet for å vokse forbi vinduet og bli klippet. */
.plugin-page { min-height: 0; grid-template-rows: minmax(0, 1fr); }
.plugin-sidebar { min-height: 0; max-height: 100%; }
.plugin-canvas { min-height: 0; max-height: 100%; }
.ftb-stage { min-height: 0; max-height: 100%; overflow-y: auto; }

/* Nettverksklode (0.2.0) */
.kk-only-kart[hidden], .kk-only-klode[hidden] { display: none; }
.kk-tabs .kk-tab { white-space: nowrap; }
